import{_ as a,o as n,c as t,ae as s}from"./chunks/framework.DBosx3SP.js";const h=JSON.parse('{"title":"Rendering Overview","description":"","frontmatter":{},"headers":[],"relativePath":"rendering/overview.md","filePath":"rendering/overview.md","lastUpdated":1792996843000}'),i={name:"rendering/overview.md"};function o(r,e,c,l,d,p){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="rendering-overview" tabindex="-1">Rendering Overview <a class="header-anchor" href="#rendering-overview" aria-label="Permalink to &quot;Rendering Overview&quot;">​</a></h1><p>Input: Plot<br> Output: Frame (Texture or File)</p><h2 id="_1-tree-expansion" tabindex="-1">1. Tree Expansion <a class="header-anchor" href="#_1-tree-expansion" aria-label="Permalink to &quot;1. Tree Expansion&quot;">​</a></h2><p>The <code>Plot</code> tree is expanded into a <code>PlotInstance</code> tree.<br><code>Scale</code> values are instantiated as <code>ScaleInstance</code> values.<br><code>Geometry</code> values are instantiated as <code>GeometryInstance</code> values.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Facet                      Facet</span></span>
<span class="line"><span>╰─ Cartesian2              ├─ Cartesian2</span></span>
<span class="line"><span>   ├─ Scatter     Expand   │  ├─ Scatter</span></span>
<span class="line"><span>   ╰─ Bar          ──▶     │  ╰─ Bar</span></span>
<span class="line"><span>                           ╰─ Cartesian2</span></span>
<span class="line"><span>                              ├─ Scatter</span></span>
<span class="line"><span>                              ╰─ Bar</span></span></code></pre></div><p>During expansion:</p><ul><li><code>Facet</code> expands one <code>Plot</code> into multiple <code>PlotInstance</code> values.</li><li>Shared scales use the same <code>ScaleInstanceId</code>.</li><li>A <code>ColorAttribute</code> or <code>ShapeAttribute</code> is resolved to an actual series.</li></ul><h2 id="_2-plotinstance-tree-traversal-dfs" tabindex="-1">2. PlotInstance Tree Traversal (DFS) <a class="header-anchor" href="#_2-plotinstance-tree-traversal-dfs" aria-label="Permalink to &quot;2. PlotInstance Tree Traversal (DFS)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Facet           - (1)</span></span>
<span class="line"><span>├─ Cartesian2   - (2)</span></span>
<span class="line"><span>│  ├─ Scatter</span></span>
<span class="line"><span>│  ╰─ Bar</span></span>
<span class="line"><span>╰─ Cartesian2   - (3)</span></span>
<span class="line"><span>   ├─ Scatter</span></span>
<span class="line"><span>   ╰─ Bar</span></span></code></pre></div><p>Traversing the tree produces a flattened plot-instance list: <code>[Facet, Cartesian2, Cartesian2]</code>.</p><ul><li>2-1. Scale: update each <code>ScaleInstance</code> minimum and maximum from the data. Shared scales update the same <code>ScaleInstance</code>.</li><li>2-2. Layout: collect layout constraints from each <code>PlotInstance</code>.</li><li>2-3. Compile (parallel): compile <code>Vec&lt;PlotInstance&gt;</code> into <code>Vec&lt;PrimitiveSet&gt;</code>. Each <code>PlotInstance</code> can generate multiple <code>PrimitiveSet</code> values.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cartesian2   -&gt;  PrimitiveSet { lines for axis spines, texts for tick labels, rect for background, .. }</span></span>
<span class="line"><span>├─ Scatter   -&gt;  PrimitiveSet { markers }</span></span>
<span class="line"><span>╰─ Bar       -&gt;  PrimitiveSet { rects, texts }</span></span></code></pre></div><p>Layout depends on scale computation because tick labels affect its constraints.</p><h2 id="_3-render-to-a-destination" tabindex="-1">3. Render to a Destination <a class="header-anchor" href="#_3-render-to-a-destination" aria-label="Permalink to &quot;3. Render to a Destination&quot;">​</a></h2><ul><li><code>SvgRenderer</code> renders each <code>PrimitiveSet</code> as SVG elements.</li><li><code>GpuRenderer</code> renders each <code>PrimitiveSet</code> to a texture.</li><li><code>Plot::save(..)</code> uses <code>GpuRenderer</code> to draw to an offscreen texture and write the result to an image file.</li><li><code>Plot::show(..)</code> opens a winit window and uses <code>GpuRenderer</code> to draw to the window&#39;s surface texture.</li></ul><p>Each <code>PlotInstance</code> is drawn with its own scissor rect.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li>How do we reuse a <code>wgpu::Buffer</code> between frames? See <a href="/ezel/dx/dataflow">Dataflow</a>.</li><li>How do we render a VDOM-like tree of <code>PlotInstance</code> and <code>Geometry</code> values without expensive VDOM diffing? See <a href="/ezel/rendering/id-system">IdInterner</a>.</li></ul>`,18)])])}const v=a(i,[["render",o]]);export{h as __pageData,v as default};
